  1	package ly.com.tahaben.notification_filter_domain.delivery
  2	
  3	import ly.com.tahaben.notification_filter_domain.model.BudgetSpendEntry
  4	import ly.com.tahaben.notification_filter_domain.model.NotificationItem
  5	import ly.com.tahaben.notification_filter_domain.model.NotificationPriority
  6	import ly.com.tahaben.notification_filter_domain.model.NotificationSchedulePeriod
  7	import ly.com.tahaben.notification_filter_domain.model.PriorityDeliverySetting
  8	
  9	enum class NotificationRemovalReason {
 10	    /** The source app cancelled its notification: explicit, clears a queued row. */
 11	    SOURCE_APP_CANCELLED,
 12	
 13	    /** The user swiped or tapped away a Farhan proxy: explicit. */
 14	    USER_DISMISSED,
 15	
 16	    /** Farhan's own interception or snooze removal: not a cancellation. */
 17	    FARHAN_INTERCEPTED,
 18	
 19	    /** The user opened the source app: not a cancellation by itself. */
 20	    SOURCE_APP_OPENED,
 21	    INBOX_CLEARED,
 22	}
 23	
 24	sealed interface PostResult {
 25	    data object Posted : PostResult
 26	    data class Failed(val reason: String) : PostResult
 27	}
 28	
 29	sealed interface DeliveryOutcome {
 30	    val id: String
 31	    data class Delivered(override val id: String) : DeliveryOutcome
 32	    /** Stored and waiting: cadence not due, or no budget. */
 33	    data class Deferred(override val id: String) : DeliveryOutcome
 34	    /** Ambiguous callback history was evicted. The persisted row remains available in the inbox. */
 35	    data class Invalidated(override val id: String) : DeliveryOutcome
 36	    /** An explicit cancellation won: nothing posted, nothing spent. */
 37	    data class Cleared(override val id: String) : DeliveryOutcome
 38	    data class PostFailed(override val id: String, val reason: String) : DeliveryOutcome
 39	    /** External effect succeeded; storage will be retried before another mutation, without reposting. */
 40	    data class CommitPending(override val id: String) : DeliveryOutcome
 41	}
 42	
 43	/** Row storage with Room semantics: [upsert] replaces every column, [markCleared] on a missing id does nothing. */
 44	interface DeliveryRowStore {
 45	    suspend fun upsert(item: NotificationItem)
 46	    suspend fun find(id: String): NotificationItem?
 47	    suspend fun markCleared(id: String)
 48	    suspend fun markDelivered(id: String)
 49	    suspend fun pending(maxPriorityLevel: Int): List<NotificationItem>
 50	    suspend fun invalidateBefore(session: String, order: Long)
 51	    suspend fun nextHead(after: NotificationItem): NotificationItem? = null
 52	}
 53	
 54	interface DeliveryBudgetStore {
 55	    suspend fun read(): DeliveryBudgetState
 56	    suspend fun write(state: DeliveryBudgetState)
 57	    suspend fun appendSpend(entry: BudgetSpendEntry)
 58	}
 59	
 60	/** Android-bound in production (NotificationManager). Must report failure, not hide it. */
 61	interface ProxyNotificationPoster {
 62	    suspend fun post(item: NotificationItem): PostResult
 63	    suspend fun refresh(item: NotificationItem): PostResult = PostResult.Posted
 64	}
 65	
 66	/** Reads of settings that can change between calls. */
 67	interface DeliveryEnvironment {
 68	    fun schedule(): List<NotificationSchedulePeriod>
 69	    fun settings(): Map<NotificationPriority, PriorityDeliverySetting>
 70	    fun timeContext(): DeliveryTimeContext
 71	    fun queuePreferences(): Map<String, AppQueuePreference>
 72	    fun activeSourceKeys(): Set<String> = emptySet()
 73	}
 74	
 75	/**
 76	 * One owner for authorization and spend. CLAIM(serialized-budget), CLAIM(post-failure-no-spend):
 77	 * [NotificationDeliveryCoordinatorTest]. The injected gate is shared with ScheduleWriter.
 78	 * Posting is an external effect; durable adapters must document their crash boundary.
 79	 */
 80	class NotificationDeliveryCoordinator(
 81	    private val rows: DeliveryRowStore,
 82	    private val budget: DeliveryBudgetStore,
 83	    private val poster: ProxyNotificationPoster,
 84	    private val environment: DeliveryEnvironment,
 85	    private val gate: DeliveryGate = DeliveryGate(),
 86	    private val eventCapacity: Int = MAX_EVENT_KEYS,
 87	) {
 88	    private data class Event(val order: Long, val removed: Boolean, val lastRemoval: Long, val accepted: Long, val bypassed: Boolean = false, val appliedRemoval: Long = 0)
 89	    private val events = linkedMapOf<String, Event>()
 90	    private val legacyRemovals = linkedMapOf<String, Long>()
 91	    private var sequence = 0L
 92	    private var discardedBefore = 0L
 93	    private val sourceSession = java.util.UUID.randomUUID().toString()
 94	    private var persistedInvalidation = 0L
 95	    private data class Completion(val id: String, val state: DeliveryBudgetState, val entry: BudgetSpendEntry?,
 96	        var rowSaved: Boolean = false, var budgetSaved: Boolean = false)
 97	    private var completion: Completion? = null
 98	
 99	    init { require(eventCapacity > 0); gate.recover = { finishCompletion(); persistInvalidations() } }
100	
101	    private suspend fun persistInvalidations() {
102	        val cutoff = synchronized(this) { discardedBefore }
103	        if (cutoff > persistedInvalidation) {
104	            rows.invalidateBefore(sourceSession, cutoff)
105	            persistedInvalidation = cutoff
106	        }
107	    }
108	    private fun ambiguous(item: NotificationItem): Boolean = synchronized(this) {
109	        item.sourceSession == sourceSession && item.sourceEventOrder > 0 && item.sourceEventOrder <= discardedBefore
110	    }
111	
112	    private suspend fun finishCompletion() {
113	        val pending = completion ?: return
114	        if (!pending.rowSaved) { rows.markDelivered(pending.id); pending.rowSaved = true }
115	        if (!pending.budgetSaved) { budget.write(pending.state); pending.budgetSaved = true }
116	        pending.entry?.let { budget.appendSpend(it) }
117	        completion = null
118	    }
119	
120	    @Synchronized private fun invalidateAll() { discardedBefore = ++sequence; events.clear() }
121	
122	
123	    /** Capture on the listener callback, before async discovery/classification. No private data is logged.
124	     * At capacity, conservatively refuse callbacks older than the evicted event, rather than resurrect them.
125	     */
126	    @Synchronized
127	    fun captureEvent(id: String, removed: Boolean = false, bypassed: Boolean = false): Long {
128	        val order = ++sequence
129	        val previous = events.remove(id)
130	        events[id] = Event(order, removed, if (removed) order else previous?.lastRemoval ?: 0, previous?.accepted ?: 0, bypassed, previous?.appliedRemoval ?: 0)
131	        if (events.size > eventCapacity) {
132	            val oldest = events.entries.first()
133	            discardedBefore = maxOf(discardedBefore, oldest.value.order)
134	            events.remove(oldest.key)
135	        }
136	        return order
137	    }
138	
139	    @Synchronized
140	    private fun stale(id: String, order: Long?, timestamp: Long): Boolean =
141	        if (order != null) order <= discardedBefore || events[id]?.let { it.order > order || it.removed } == true
142	        else (legacyRemovals[id] ?: Long.MIN_VALUE) >= timestamp
143	
144	    @Synchronized
145	    private fun explicitlyRemoved(id: String): Boolean = events[id]?.let { it.lastRemoval > it.accepted } == true
146	    @Synchronized private fun removalApplied(id: String, order: Long) {
147	        events[id]?.let { events[id] = it.copy(appliedRemoval = maxOf(it.appliedRemoval, order)) }
148	    }
149	    @Synchronized private fun bypassed(id: String): Boolean = events[id]?.bypassed == true
150	    @Synchronized private fun unprocessed(id: String): Boolean = events[id]?.let { it.order > it.accepted && !it.removed } == true
151	    @Synchronized private fun accept(id: String, order: Long?) {
152	        if (order != null) events[id]?.let { events[id] = it.copy(accepted = order) }
153	    }
154	
155	    suspend fun onArrival(
156	        item: NotificationItem,
157	        effectivePriority: NotificationPriority,
158	        eventOrder: Long? = null,
159	        passThrough: Boolean = false,
160	        captureActions: (() -> Unit)? = null,
161	        sourceStillCurrent: (() -> Boolean)? = null,
162	    ): DeliveryOutcome = gate.run {
163	        if (stale(item.id, eventOrder, item.timestamp)) return@run DeliveryOutcome.Cleared(item.id)
164	        if (sourceStillCurrent?.invoke() == false) return@run DeliveryOutcome.Deferred(item.id)
165	        val previous = rows.find(item.id)
166	        val delivered = previous?.isDelivered == true && !previous.isCleared && !explicitlyRemoved(item.id)
167	        val updated = item.copy(priority = effectivePriority, isRead = previous?.isRead ?: item.isRead,
168	            isDelivered = delivered || passThrough, isCleared = false, deliveryInvalidated = false,
169	            sourceSession = if (eventOrder != null) sourceSession else item.sourceSession,
170	            sourceEventOrder = eventOrder ?: item.sourceEventOrder)
171	        rows.upsert(updated)
172	        if (stale(item.id, eventOrder, item.timestamp)) { rows.markCleared(item.id); return@run DeliveryOutcome.Cleared(item.id) }
173	        accept(item.id, eventOrder)
174	        captureActions?.invoke()
175	        if (passThrough) return@run DeliveryOutcome.Delivered(item.id)
176	        if (delivered) {
177	            return@run when (val post = postSafely(updated, refresh = true)) {
178	                PostResult.Posted -> DeliveryOutcome.Delivered(item.id)
179	                is PostResult.Failed -> DeliveryOutcome.PostFailed(item.id, post.reason)
180	            }
181	        }
182	        val setting = environment.settings()[effectivePriority] ?: PriorityDeliverySetting.defaultFor(effectivePriority)
183	        if (!NotificationDeliveryPolicy.shouldDeliverOnArrival(setting)) return@run DeliveryOutcome.Deferred(item.id)
184	        if (stale(item.id, eventOrder, item.timestamp)) DeliveryOutcome.Cleared(item.id)
185	        else if (sourceStillCurrent?.invoke() == false) DeliveryOutcome.Deferred(item.id) else deliver(updated)
186	    }
187	
188	    suspend fun onRemoved(id: String, reason: NotificationRemovalReason, atMillis: Long, eventOrder: Long? = null) {
189	        if (reason != NotificationRemovalReason.SOURCE_APP_CANCELLED && reason != NotificationRemovalReason.USER_DISMISSED && reason != NotificationRemovalReason.INBOX_CLEARED) return
190	        if (eventOrder == null) synchronized(this) {
191	            legacyRemovals[id] = maxOf(legacyRemovals[id] ?: Long.MIN_VALUE, atMillis)
192	            if (legacyRemovals.size > eventCapacity) legacyRemovals.remove(legacyRemovals.keys.first())
193	        }
194	        gate.run {
195	            if (eventOrder != null && synchronized(this) { (events[id]?.accepted ?: 0) > eventOrder }) return@run
196	            val current = rows.find(id)
197	            if (eventOrder == null && current != null && current.timestamp > atMillis) return@run
198	            rows.markCleared(id)
199	            if (eventOrder != null) removalApplied(id, eventOrder)
200	        }
201	    }
202	
203	    suspend fun clearInbox(id: String, delete: suspend () -> Unit) {
204	        val order = captureEvent(id, removed = true)
205	        gate.run { rows.markCleared(id); delete(); removalApplied(id, order) }
206	    }
207	    suspend fun clearAll(delete: suspend () -> Unit) {
208	        invalidateAll()
209	        gate.run { delete() }
210	    }
211	
212	    suspend fun onBatchTick(): List<DeliveryOutcome> = gate.run {
213	        val removals = synchronized(this) { events.filterValues { it.lastRemoval > it.accepted && it.appliedRemoval < it.lastRemoval }.map { it.key to it.value.lastRemoval } }
214	        removals.forEach { (id, order) -> rows.markCleared(id); removalApplied(id, order) }
215	        val settings = environment.settings()
216	        val time = environment.timeContext()
217	        val visibleSources = environment.activeSourceKeys()
218	        val pending = rows.pending(NotificationPriority.LOW.level).filter {
219	            NotificationDeliveryPolicy.shouldDeliverOnBatchTick(it.priority, settings, time)
220	        }.toMutableList()
221	        val outcomes = mutableListOf<DeliveryOutcome>()
222	        while (pending.isNotEmpty() && outcomes.size < MAX_BATCH_ATTEMPTS) {
223	            val candidate = NotificationDeliveryPolicy.orderCandidates(pending, environment.queuePreferences()).first()
224	            pending.removeAll { it.id == candidate.id }
225	            val current = rows.find(candidate.id)
226	            val outcome = if (current == null || current.isCleared || explicitlyRemoved(candidate.id)) {
227	                rows.markCleared(candidate.id)
228	                DeliveryOutcome.Cleared(candidate.id)
229	            } else if (current.deliveryInvalidated || ambiguous(current)) {
230	                persistInvalidations()
231	                DeliveryOutcome.Invalidated(candidate.id)
232	            } else if (current.isDelivered || bypassed(candidate.id) || candidate.id in visibleSources) DeliveryOutcome.Deferred(candidate.id)
233	            else deliver(current)
234	            outcomes += outcome
235	            if (outcome is DeliveryOutcome.CommitPending) break
236	            if (outcome is DeliveryOutcome.Delivered) {
237	                rows.nextHead(candidate)?.let { next -> if (pending.none { it.id == next.id }) pending += next }
238	            }
239	        }
240	        outcomes
241	    }
242	
243	    private suspend fun deliver(item: NotificationItem): DeliveryOutcome {
244	        // Recheck callback-side tombstones at the effect boundary, even if removal work is queued.
245	        if (explicitlyRemoved(item.id) || rows.find(item.id)?.isCleared != false) {
246	            rows.markCleared(item.id)
247	            return DeliveryOutcome.Cleared(item.id)
248	        }
249	        if (item.deliveryInvalidated || ambiguous(item)) { persistInvalidations(); return DeliveryOutcome.Invalidated(item.id) }
250	        if (bypassed(item.id) || unprocessed(item.id)) return DeliveryOutcome.Deferred(item.id)
251	        val time = environment.timeContext()
252	        val schedule = environment.schedule()
253	        val setting = environment.settings()[item.priority] ?: PriorityDeliverySetting.defaultFor(item.priority)
254	        val decision = NotificationDeliveryPolicy.canDeliverNow(item.priority, setting, schedule, time, budget.read())
255	        if (!decision.canDeliver) return DeliveryOutcome.Deferred(item.id)
256	        if (explicitlyRemoved(item.id) || rows.find(item.id)?.isCleared != false) {
257	            rows.markCleared(item.id)
258	            return DeliveryOutcome.Cleared(item.id)
259	        }
260	        if (ambiguous(item)) { persistInvalidations(); return DeliveryOutcome.Invalidated(item.id) }
261	        if (bypassed(item.id) || unprocessed(item.id)) return DeliveryOutcome.Deferred(item.id)
262	        return when (val post = postSafely(item)) {
263	            is PostResult.Failed -> DeliveryOutcome.PostFailed(item.id, post.reason)
264	            PostResult.Posted -> {
265	                val charged = NotificationDeliveryPolicy.recordPassthrough(item.priority, setting, schedule, time.scheduleMinuteOfDay, decision.updatedBudget)
266	                val entry = if (setting.budgetBehavior == ly.com.tahaben.notification_filter_domain.model.BudgetBehavior.RESPECTING && item.priority.pointCost > 0)
267	                    BudgetSpendEntry(item.appName.orEmpty(), item.title.orEmpty(), item.priority, item.priority.pointCost,
268	                        System.currentTimeMillis(), charged.periodStartMinute, charged.accountingId, java.util.UUID.randomUUID().toString()) else null
269	                // At most one unresolved effect is retained. All subsequent mutations recover it under this gate.
270	                completion = Completion(item.id, charged, entry)
271	                try { finishCompletion() }
272	                catch (cancelled: kotlinx.coroutines.CancellationException) { throw cancelled }
273	                catch (_: Exception) { return DeliveryOutcome.CommitPending(item.id) }
274	                DeliveryOutcome.Delivered(item.id)
275	            }
276	        }
277	    }
278	
279	    private suspend fun postSafely(item: NotificationItem, refresh: Boolean = false): PostResult = try {
280	        if (refresh) poster.refresh(item) else poster.post(item)
281	    } catch (cancelled: kotlinx.coroutines.CancellationException) {
282	        throw cancelled
283	    } catch (_: Exception) {
284	        PostResult.Failed("notification_post_failed")
285	    }
286	
287	    companion object { const val MAX_EVENT_KEYS = 4096; const val MAX_BATCH_ATTEMPTS = 256 }
288	}
